    /**
     * Method to retrieve the Payment via PaymentFetchOneSummary
     * @param 	summary PaymentFetchOneSummary 
     * @return 	PaymentFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Payment getPayment( PaymentFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PaymentFetchOneSummary arg cannot be null" );
    	
    	Payment entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Payment
        	// --------------------------------------
        	CompletableFuture<Payment> futureEntity = queryGateway.query(new FindPaymentQuery( new LoadPaymentFilter( summary.getPaymentId() ) ), ResponseTypes.instanceOf(Payment.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Payment with id " + summary.getPaymentId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


